while (Get-Process -Id 11536 -ErrorAction SilentlyContinue) { Start-Sleep 60 }; Set-Location C:\JuliaProjects\More_zodi; $env:ZODI_DATA = "z500"; "$(Get-Date -Format "yyyy-MM-dd HH:mm")  round 25 start" | Out-File sweeps\round25.log -Append -Encoding utf8; $p = Start-Process julia -ArgumentList "-t 5 --project=. sweeps/run_threaded.jl sweeps/configs_v25.jl" -RedirectStandardOutput sweeps\round25_run.log -RedirectStandardError sweeps\round25_run.err -WindowStyle Hidden -PassThru; Start-Sleep 10; Get-CimInstance Win32_Process -Filter "ParentProcessId=$($p.Id)" | ForEach-Object { try { (Get-Process -Id $_.ProcessId -ErrorAction Stop).PriorityClass = "BelowNormal" } catch {} }; $p.WaitForExit(); "$(Get-Date -Format "yyyy-MM-dd HH:mm")  round 25 done" | Out-File sweeps\round25.log -Append -Encoding utf8
